#include <iostream>
#include <vector>
using namespace std;

class NQueens {
private:
    int n;
    vector<vector<int>> board;
    vector<vector<vector<int>>> solutions;

    bool isSafe(int row, int col) {
        // Check column
        for (int i = 0; i < row; i++) {
            if (board[i][col] == 1) return false;
        }

        // Check upper left diagonal
        for (int i = row - 1, j = col - 1; i >= 0 && j >= 0; i--, j--) {
            if (board[i][j] == 1) return false;
        }

        // Check upper right diagonal
        for (int i = row - 1, j = col + 1; i >= 0 && j < n; i--, j++) {
            if (board[i][j] == 1) return false;
        }

        return true;
    }

    void solve(int row) {
        if (row == n) {
            solutions.push_back(board);
            return;
        }

        for (int col = 0; col < n; col++) {
            if (isSafe(row, col)) {
                board[row][col] = 1;
                solve(row + 1);
                board[row][col] = 0;
            }
        }
    }

public:
    NQueens(int size) : n(size) {
        board.resize(n, vector<int>(n, 0));
    }

    vector<vector<vector<int>>> solveNQueens() {
        solve(0);
        return solutions;
    }
};

int main() {
    NQueens nq(4);
    auto solutions = nq.solveNQueens();

    cout << "Found " << solutions.size() << " solutions for 4-Queens" << endl;

    for (int i = 0; i < solutions.size(); i++) {
        cout << "\nSolution " << i + 1 << ":" << endl;
        for (auto& row : solutions[i]) {
            for (int val : row) {
                cout << val << " ";
            }
            cout << endl;
        }
    }

    return 0;
}

